WITH enriched AS (SELECT s.id, s.customer_id, s.balance, s.opened_date, p.segment, p.country FROM accounts s INNER JOIN customers p ON s.customer_id <=> p.id WHERE p.name LIKE 'Mia%'), matched_keys AS (SELECT id, customer_id FROM enriched INTERSECT ALL SELECT id, customer_id FROM accounts WHERE balance > 73000), reconciled AS (SELECT s.* FROM enriched s INNER JOIN matched_keys k ON s.id = k.id AND s.customer_id = k.customer_id), metrics AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY balance NULLS FIRST) AS balance_percent_rank, CUME_DIST() OVER (PARTITION BY segment ORDER BY balance DESC NULLS LAST) AS balance_cume_dist FROM reconciled), filtered AS (SELECT id, balance, opened_date, country, balance_percent_rank, balance_cume_dist, DATE_TRUNC('YEAR', opened_date) AS opened_date_period FROM metrics WHERE country IS NOT DISTINCT FROM 'US' AND country IN ('JP', 'TH', 'US')), remaining_keys AS (SELECT id FROM filtered EXCEPT SELECT id FROM accounts WHERE account_type IN ('LOAN', 'CREDIT', 'CHECKING')), reconciled_accounts AS (SELECT s.* FROM filtered s INNER JOIN remaining_keys k ON s.id = k.id) SELECT CASE WHEN balance_cume_dist >= 0.87 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_cume_dist_tier, CASE WHEN balance >= 83000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, SUM(balance) AS total_balance, SUM(CASE WHEN country = 'SG' THEN balance ELSE 0 END) AS sg_balance, AVG(balance_percent_rank) FILTER (WHERE country = 'US') AS us_avg_balance_percent_rank, GROUPING(CASE WHEN balance_cume_dist >= 0.87 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM reconciled_accounts GROUP BY CUBE (CASE WHEN balance_cume_dist >= 0.87 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN balance >= 83000 THEN 'PREMIUM' ELSE 'STANDARD' END);
